# legal_corpus/setup.py
import os

LEGAL_CORPUS_ROOT = "/legal_corpus/"

def create_directories():
    categories = [
        "01_Constitution",
        "02_Legislation",
        "03_Case_Law",
        "04_Procedure",
        "05_Specialized_Law",
        "06_International_Law",
        "07_Legal_Reasoning"
    ]
    for category in categories:
        path = os.path.join(LEGAL_CORPUS_ROOT, category)
        os.makedirs(path, exist_ok=True)
        metadata_path = os.path.join(path, "metadata.json")
        if not os.path.exists(metadata_path):
            with open(metadata_path, 'w') as f:
                f.write("{}")
